      ];
      const pcts = AllocationEngine.computeEffectivePercentages(allocations, 1000);

      expect(pcts['A']).toBe(30);
      expect(pcts['B']).toBe(70);
    });

    it('should return empty object for zero total', () => {
      const pcts = AllocationEngine.computeEffectivePercentages([], 0);
      expect(pcts).toEqual({});
    });

    it('should merge multiple allocation results', () => {
      const r1: AllocationResult = {
        ruleId: 'r1',
        allocations: [
          { target: 'A', amount: 100, percentage: 50 },
          { target: 'B', amount: 100, percentage: 50 },
        ],
        totalAllocated: 200,
        timestamp: '',
        auditComment: '',
      };
      const r2: AllocationResult = {
        ruleId: 'r2',
        allocations: [
          { target: 'A', amount: 200, percentage: 40 },
          { target: 'C', amount: 300, percentage: 60 },
        ],
        totalAllocated: 500,
        timestamp: '',
        auditComment: '',
      };
      const merged = AllocationEngine.mergeAllocationResults([r1, r2]);

      expect(merged['A']).toBe(300);
      expect(merged['B']).toBe(100);
      expect(merged['C']).toBe(300);
    });

    it('should detect circular references', () => {
      const cycles = AllocationEngine.detectCircularReferences({
        A: { B: 50 },
        B: { A: 30 },
      });

      expect(cycles.length).toBeGreaterThan(0);
      expect(cycles[0]).toContain('A');
      expect(cycles[0]).toContain('B');
    });

    it('should return empty for no circular references', () => {
      const cycles = AllocationEngine.detectCircularReferences({
        A: { C: 50 },
        B: { C: 50 },
        C: {},
      });

      expect(cycles).toHaveLength(0);
    });

    it('should detect three-way circular references', () => {
      const cycles = AllocationEngine.detectCircularReferences({
        A: { B: 10 },
        B: { C: 10 },
        C: { A: 10 },
      });

      expect(cycles.length).toBeGreaterThan(0);
    });
  });

  // ---------------------------------------------------------------------------
  // EDGE CASE TESTS
  // ---------------------------------------------------------------------------

  describe('Edge Cases', () => {
    it('should handle direct allocation with many targets', () => {
      const targets = Array.from({ length: 20 }, (_, i) => target(`Dept${i}`, 5));
      const rule = createDirectRule('e1', 'Many Targets', targets);
      const result = AllocationEngine.allocateDirect(rule, 100000);

      expect(result.allocations).toHaveLength(20);
      expect(result.totalAllocated).toBe(100000);
    });

    it('should handle driver allocation with uneven weights', () => {
      const rule = createDriverRule('e2', 'Uneven', [target('A', 0, 10), target('B', 0, 1)]);
      const result = AllocationEngine.allocateByDriver(rule, 1100, { A: 10, B: 10 });

      // A: 10*10=100, B: 10*1=10, total=110
      // A: 100/110 * 1100 = 1000, B: 10/110 * 1100 = 100
      expect(result.allocations[0].amount).toBe(1000);
      expect(result.allocations[1].amount).toBe(100);
    });

    it('should preserve percentage in direct allocation result', () => {
      const rule = createDirectRule('e3', 'Pct Preserve', [target('A', 75), target('B', 25)]);
      const result = AllocationEngine.allocateDirect(rule, 4000);

      expect(result.allocations[0].percentage).toBe(75);
      expect(result.allocations[1].percentage).toBe(25);
    });

    it('should handle step-down with single service and single production', () => {
      const config: StepDownConfig = {
        serviceDepartments: ['Svc'],
        productionDepartments: ['Prod'],
        serviceCosts: { Svc: 5000 },
        servicePercentages: { Svc: { Prod: 100 } },
      };
      const results = AllocationEngine.allocateStepDown(config);

      expect(results).toHaveLength(1);
      expect(results[0].allocations[0].amount).toBe(5000);
      expect(results[0].allocations[0].target).toBe('Prod');
    });

    it('should handle reciprocal allocation with asymmetric services', () => {
      const config: ReciprocalConfig = {
        departments: ['A', 'B'],
        departmentCosts: { A: 1000, B: 5000 },
        servicePercentages: {
          A: { B: 10 },
          B: { A: 5 },
        },
      };
      const results = AllocationEngine.allocateReciprocal(config);

      // A total = 1000 + 0.05 * B_total
      // B total = 5000 + 0.10 * A_total
      expect(results).toHaveLength(2);
      const aResult = results.find((r) => r.ruleId === 'reciprocal-A')!;
      const bResult = results.find((r) => r.ruleId === 'reciprocal-B')!;
      expect(aResult.totalAllocated).toBeGreaterThan(1000);
      expect(bResult.totalAllocated).toBeGreaterThan(5000);
    });

    it('should handle timestamp generation', () => {
      const rule = createDirectRule('t1', 'Time', [target('A', 100)]);
      const result = AllocationEngine.allocateDirect(rule, 100);

      // Timestamp should be a valid ISO date string
      expect(() => new Date(result.timestamp)).not.toThrow();
      expect(new Date(result.timestamp).getTime()).not.toBeNaN();
    });

    it('should handle step-down allocation percentages at boundaries', () => {
      const config: StepDownConfig = {
        serviceDepartments: ['IT'],
        productionDepartments: ['A', 'B'],
        serviceCosts: { IT: 100 },
        servicePercentages: {
          IT: { A: 0.01, B: 99.99 },
        },
      };
      const results = AllocationEngine.allocateStepDown(config);

      expect(results[0].allocations).toHaveLength(2);
      const total = results[0].allocations.reduce((s, a) => s + a.amount, 0);
      expect(total).toBe(100);
    });
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import {CellCommentEngine} from './CellCommentEngine';

describe('CellCommentEngine', () => {
  let engine: CellCommentEngine;

  beforeEach(() => {
    engine = new CellCommentEngine();
  });

  it('should initialize with empty comments', () => {
    expect(engine.getComments('A1')).toEqual([]);
    expect(engine.getCommentCount('A1')).toBe(0);
  });

  it('should add a comment', () => {
    const comment = engine.addComment('A1', 'Alice', 'Test comment');
    expect(comment.id).toMatch(/^cmt-/);
    expect(comment.cellKey).toBe('A1');
    expect(comment.author).toBe('Alice');
    expect(comment.text).toBe('Test comment');
    expect(comment.resolved).toBe(false);
    expect(comment.parentId).toBeNull();
  });

  it('should get comments for a cell', () => {
    engine.addComment('A1', 'Alice', 'Comment 1');
    engine.addComment('A1', 'Bob', 'Comment 2');
    engine.addComment('B1', 'Alice', 'Comment 3');

    expect(engine.getComments('A1')).toHaveLength(2);
    expect(engine.getComments('B1')).toHaveLength(1);
    expect(engine.getComments('C1')).toEqual([]);
  });

  it('should reply to a comment', () => {
    const parent = engine.addComment('A1', 'Alice', 'Parent');
    const reply = engine.replyTo(parent.id, 'Bob', 'Reply');

    expect(reply).not.toBeNull();
    expect(reply!.parentId).toBe(parent.id);
    expect(reply!.cellKey).toBe('A1');
  });

  it('should return null when replying to non-existent comment', () => {
    const reply = engine.replyTo('non-existent', 'Bob', 'Reply');
    expect(reply).toBeNull();
  });

  it('should resolve and unresolve a comment', () => {
    const comment = engine.addComment('A1', 'Alice', 'Test');
    expect(engine.resolveComment(comment.id)).toBe(true);
    expect(engine.getComments('A1')[0].resolved).toBe(true);

    expect(engine.unresolveComment(comment.id)).toBe(true);
    expect(engine.getComments('A1')[0].resolved).toBe(false);
  });

  it('should return false when resolving non-existent comment', () => {
    expect(engine.resolveComment('non-existent')).toBe(false);
  });

  it('should delete a comment', () => {
    const comment = engine.addComment('A1', 'Alice', 'Test');
    expect(engine.deleteComment(comment.id)).toBe(true);
    expect(engine.getComments('A1')).toHaveLength(0);
  });

  it('should return false when deleting non-existent comment', () => {
    expect(engine.deleteComment('non-existent')).toBe(false);
  });

  it('should extract mentions from text', () => {
    const comment = engine.addComment('A1', 'Alice', 'Hey @Bob and @Charlie');
    expect(comment.mentions).toContain('Bob');
    expect(comment.mentions).toContain('Charlie');
  });

  it('should count comments correctly', () => {
    engine.addComment('A1', 'Alice', 'C1');
    engine.addComment('A1', 'Bob', 'C2');
    engine.addComment('B1', 'Alice', 'C3');
    expect(engine.getCommentCount('A1')).toBe(2);
    expect(engine.getCommentCount('B1')).toBe(1);
  });

  it('should export comments', () => {
    engine.addComment('A1', 'Alice', 'Test');
    const exported = engine.exportAll();
    expect(exported.length).toBeGreaterThan(0);
    expect(exported[0].cellKey).toBe('A1');
  });

  it('should import comments', () => {
    const data = [
      {
        cellKey: 'A1',
        comments: [
          {
            id: 'cmt-1',
            cellKey: 'A1',
            author: 'Alice',
            text: 'Imported',
            createdAt: new Date().toISOString(),
            resolved: false,
            parentId: null,
            mentions: [],
          },
        ],
      },
    ];
    engine.importData(data);
    expect(engine.getComments('A1')).toHaveLength(1);
  });
});

import {describe, it, expect} from 'vitest';
import {
  evaluateRule,
  evaluateRules,
  reorderRules,
  createVarianceHighlightRule,
  createNegativeVarianceRule,
  _createGrowthRateRule,
  _createBudgetVsActualRule,
  DEFAULT_RULES,
  type ConditionalFormatRule,
} from './ConditionalFormattingEngine';

describe('ConditionalFormattingEngine', () => {
  it('should have default rules', () => {
    expect(DEFAULT_RULES.length).toBe(4);
  });

  it('should create variance highlight rule', () => {
    const rule = createVarianceHighlightRule();
    expect(rule.id).toBe('variance-highlight');
    expect(rule.name).toBe('Variance Highlighting');
    expect(rule.enabled).toBe(true);
  });

  it('should create negative variance rule', () => {
    const rule = createNegativeVarianceRule();
    expect(rule.id).toBe('variance-negative');
    expect(rule.condition.operator).toBe('lessThan');
  });

  it('should evaluate cellValue rule - greaterThan', () => {
    const rule: ConditionalFormatRule = {
      id: 'test-1',
      name: 'High',
      enabled: true,
      priority: 100,
      condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 50 },
      visualType: 'backgroundColor',
      style: { backgroundColor: '#ff0000' },
    };
    const result = evaluateRule(rule, 100);
    expect(result.matched).toBe(true);
  });

  it('should evaluate cellValue rule - lessThan', () => {
    const rule: ConditionalFormatRule = {
      id: 'test-2',
      name: 'Low',
      enabled: true,
      priority: 100,
      condition: { ruleType: 'cellValue', operator: 'lessThan', value: 10 },
      visualType: 'backgroundColor',
      style: { backgroundColor: '#00ff00' },
    };
    expect(evaluateRule(rule, 5).matched).toBe(true);
    expect(evaluateRule(rule, 50).matched).toBe(false);
  });

  it('should evaluate cellValue rule - between', () => {
    const rule: ConditionalFormatRule = {
      id: 'test-3',
      name: 'Mid',
      enabled: true,
      priority: 100,
      condition: { ruleType: 'cellValue', operator: 'between', value: 10, value2: 20 },
      visualType: 'backgroundColor',
      style: { backgroundColor: '#ffff00' },
    };
    expect(evaluateRule(rule, 15).matched).toBe(true);
    expect(evaluateRule(rule, 5).matched).toBe(false);
    expect(evaluateRule(rule, 25).matched).toBe(false);
  });

  it('should evaluate text rule - contains', () => {
    const rule: ConditionalFormatRule = {
      id: 'test-4',
      name: 'Contains',
      enabled: true,
      priority: 100,
      condition: { ruleType: 'text', operator: 'contains', text: 'error' },
      visualType: 'textColor',
      style: { textColor: '#ff0000' },
    };
    expect(evaluateRule(rule, 'This has an error').matched).toBe(true);
    expect(evaluateRule(rule, 'Fine').matched).toBe(false);
  });

  it('should not match disabled rules', () => {
    const rule: ConditionalFormatRule = {
      id: 'test-5',
      name: 'Disabled',
      enabled: false,
      priority: 100,
      condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 0 },
      visualType: 'backgroundColor',
      style: { backgroundColor: '#ff0000' },
    };
    expect(evaluateRule(rule, 100).matched).toBe(false);
  });

  it('should reorder rules by priority', () => {
    const r1: ConditionalFormatRule = {
      id: 'r1',
      name: 'First',
      enabled: true,
      priority: 10,
      condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 0 },
      visualType: 'backgroundColor',
    };
    const r2: ConditionalFormatRule = {
      id: 'r2',
      name: 'Second',
      enabled: true,
      priority: 100,
      condition: { ruleType: 'cellValue', operator: 'lessThan', value: 100 },
      visualType: 'backgroundColor',
    };
    const reordered = reorderRules([r1, r2]);
    expect(reordered[0].name).toBe('Second');
  });

  it('should evaluate multiple rules and return highest priority match', () => {
    const rules: ConditionalFormatRule[] = [
      {
        id: 'low',
        name: 'Low',
        enabled: true,
        priority: 10,
        condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 0 },
        visualType: 'backgroundColor',
        style: { backgroundColor: '#00ff00' },
      },
      {
        id: 'high',
        name: 'High',
        enabled: true,
        priority: 100,
        condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 50 },
        visualType: 'backgroundColor',
        style: { backgroundColor: '#ff0000' },
      },
    ];
    const result = evaluateRules(rules, 100);
    expect(result).not.toBeNull();
    expect(result!.ruleId).toBe('high');
  });

  it('should return null when no rules match', () => {
    const rules: ConditionalFormatRule[] = [
      {
        id: 'test',
        name: 'Test',
        enabled: true,
        priority: 100,
        condition: { ruleType: 'cellValue', operator: 'greaterThan', value: 1000 },
        visualType: 'backgroundColor',
      },
    ];
    expect(evaluateRules(rules, 5)).toBeNull();
  });

  it('should have presets in default rules', () => {
    expect(DEFAULT_RULES.length).toBeGreaterThanOrEqual(4);
    expect(DEFAULT_RULES.some((r) => r.name.includes('Variance'))).toBe(true);
  });
});

