          ],
        },
        {
          entityId: 'sub',
          entityName: 'Sub',
          currency: 'USD',
          entries: [
            createEntry('s1', '1000', 'Cash', subCash, 'sub'),
            createEntry('s2', '3000', 'Common Stock', subEquity, 'sub'),
          ],
        },
      ];
      const ownerships: OwnershipStructure[] = [
        { parentId: 'parent', childId: 'sub', ownershipPct: 80, method: 'full' },
      ];
      const icPairs: ICPair[] = [
        {
          fromEntityId: 'parent',
          toEntityId: 'sub',
          accountCode: '1500',
          amount: 80000,
          type: 'investment',
        },
      ];

      // Step 4: Consolidate
      const result = ConsolidationEngine.consolidate(entities, ownerships, icPairs);

      // Step 5: Validate
      const _validation = ConsolidationEngine.validate(result);

      // Assertions: parent cash (200000) + sub cash (50000) = 250000, investment eliminated
      expect(result.totalAssets).toBe(250000);
      expect(result.minorityInterestDetails).toHaveLength(1);
      expect(result.eliminations.length).toBeGreaterThan(0);

      // Step 7: Verify cube has consolidated data
      // Aggregate consolidated entries by account before writing
      const aggregatedByAccount = new Map<string, number>();
      for (const entry of result.consolidatedEntries) {
        aggregatedByAccount.set(
          entry.accountCode,
          (aggregatedByAccount.get(entry.accountCode) ?? 0) + entry.amount
        );
      }
      for (const [accountCode, amount] of aggregatedByAccount) {
        await cube.writeCell('GL', {
          coords: {
            Account: `Account:${accountCode}`,
            Entity: 'Entity:parent',
            Scenario: 'Scenario:actual',
          },
          measure: 'amount',
          value: amount,
          dataType: 'consolidated',
        });
      }

      const consolidatedCash = cube.getCellValue(
        'GL',
        { Account: 'Account:1000', Entity: 'Entity:parent', Scenario: 'Scenario:actual' },
        'amount'
      );
      expect(consolidatedCash).toBe(250000);
    });
  });
});

import { describe, it, expect } from 'vitest';
import {
  ConsolidationEngine,
  type EntityData,
  type OwnershipStructure,
  type ICPair,
  type EliminationEntry,
  type _ConsolidationAdjustment,
  type FXRate,
  type VIENotification,
} from './ConsolidationEngine';
import type { GLEntry } from '@/types/sector-types';

// =============================================================================
// TEST HELPERS
// =============================================================================

function createEntry(
  id: string,
  accountCode: string,
  accountName: string,
  amount: number,
  entityId: string,
  currency = 'USD'
): GLEntry {
  return { id, accountCode, accountName, amount, currency, date: '2024-01-01', entityId };
}

function createParent(entries: GLEntry[] = []): EntityData {
  return { entityId: 'parent', entityName: 'Parent Corp', currency: 'USD', entries };
}

function createSubsidiary(
  id: string,
  name: string,
  entries: GLEntry[] = [],
  isForeign = false,
  currency = 'USD'
): EntityData {
  return { entityId: id, entityName: name, currency, entries, isForeign };
}

function createOwnership(
  parentId: string,
  childId: string,
  ownershipPct: number,
  method: 'full' | 'equity' | 'cost' = 'full'
): OwnershipStructure {
  return { parentId, childId, ownershipPct, method };
}

function createICPair(
  from: string,
  to: string,
  accountCode: string,
  amount: number,
  type: ICPair['type'] = 'receivable'
): ICPair {
  return { fromEntityId: from, toEntityId: to, accountCode, amount, type };
}

