      expect(loaded.size).toBe(0);
    });

    it('should preserve member parentId', async () => {
      const dim = createTestDimension({
        members: new Map([
          [
            'Account:Revenue',
            {
              id: 'Account:Revenue',
              code: 'Revenue',
              name: 'Revenue',
              parentId: 'Income',
              hierarchy: 'reporting',
              level: 1,
              isLeaf: true,
