            'Account:NetIncome',
            {
              id: 'Account:NetIncome',
              code: 'NetIncome',
              name: 'Net Income',
              hierarchy: 'reporting',
              level: 0,
              isLeaf: false,
              isActive: true,
              attributes: {},
