}

// --- Report Parameters ---

export interface ReportParameter {
  id: string;
  name: string;
  label: string;
  type: ParameterType;
  value: string | number | boolean;
  defaultValue: string | number | boolean;
  options?: Array<{ label: string; value: string | number }>;
