                })}
                <td className="px-4 py-3 text-right tabular-nums">{formatCurrency(grandTotal)}</td>
              </tr>
            </tfoot>
          </table>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-4">
