  const taskRows: TaskRow[] = useMemo(
    () =>
      tasks.map((t) => ({
        id: t.id,
        title: t.title,
        assignee: t.assigneeName,
        priority: t.priority,
        status: t.status,
        dueDate: t.dueDate,
      })),
    [tasks]
  );

  const activityRows: ActivityRow[] = useMemo(
    () =>
      activityLog.map((a) => ({
        id: a.id,
        user: a.userName,
        action: a.action,
        resource: a.resourceName,
        timestamp: a.timestamp,
      })),
    [activityLog]
  );

  const handleAddComment = () => {
    if (!newComment.trim() || !user) return;
    const displayName = user.name ?? `${user.firstName} ${user.lastName}`;
    addComment({
      resourceType: 'general',
      resourceId: 'collaboration',
      cellId: null,
      parentId: null,
      authorId: user.id,
      authorName: displayName,
      authorInitials: displayName
        .split(' ')
        .map((n) => n[0])
        .join('')
        .toUpperCase(),
      content: newComment,
      mentions: [],
      isResolved: false,
      resolvedAt: null,
    });
    addActivity({
      userId: user.id,
      userName: displayName,
      userEmail: user.email ?? '',
      action: 'commented',
      resourceType: 'general',
      resourceId: 'collaboration',
      resourceName: 'Collaboration',
      details: null,
    });
    setNewComment('');
