        </select>
      ),
    },
    {
      key: 'dueDate',
      header: 'Due',
      width: '120px',
      render: (v) => new Date(v).toLocaleDateString(),
    },
  ];

  const activityColumns: Column<ActivityRow>[] = [
    { key: 'user', header: 'User', width: '120px' },
    { key: 'action', header: 'Action', width: '180px' },
    { key: 'resource', header: 'Resource' },
    {
      key: 'timestamp',
      header: 'Time',
      width: '160px',
      render: (v) => new Date(v).toLocaleString(),
    },
  ];

  const pendingTasks = tasks.filter((t) => t.status === 'Pending').length;
  const inProgressTasks = tasks.filter((t) => t.status === 'InProgress').length;

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Collaboration Hub</h1>
          <p className="text-muted-foreground">Comments, tasks, and activity across your team</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={() => navigate('/collaboration/approvals')}>
            Approval Queue
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <KPIValue
              label="Comments"
              value={comments.length}
              icon={<MessageSquare className="h-4 w-4" />}
            />
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <KPIValue
              label="Pending Tasks"
              value={pendingTasks}
              icon={<Clock className="h-4 w-4" />}
            />
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <KPIValue
              label="In Progress"
              value={inProgressTasks}
              icon={<Users className="h-4 w-4" />}
            />
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <KPIValue
              label="Activity"
              value={activityLog.length}
              icon={<Activity className="h-4 w-4" />}
            />
          </CardContent>
        </Card>
      </div>

      <div className="flex gap-2 border-b">
        {(['comments', 'tasks', 'activity'] as Tab[]).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 text-sm font-medium capitalize border-b-2 transition-colors ${
              activeTab === tab
                ? 'border-primary text-primary'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {activeTab === 'comments' && (
        <div className="space-y-4">
          <Card>
            <CardContent className="p-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  placeholder="Add a comment..."
                  className="flex-1 px-3 py-2 border rounded-md text-sm"
                  onKeyDown={(e) => e.key === 'Enter' && handleAddComment()}
                />
                <Button onClick={handleAddComment} disabled={!newComment.trim()}>
                  <Send className="h-4 w-4 mr-1" /> Post
                </Button>
              </div>
            </CardContent>
          </Card>
          {commentRows.length > 0 ? (
            <DataTable data={commentRows} columns={commentColumns} />
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <MessageSquare className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No comments yet. Start the conversation above.</p>
              </CardContent>
            </Card>
          )}
        </div>
      )}

      {activeTab === 'tasks' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={() => setShowNewTask(!showNewTask)}>
              <Plus className="h-4 w-4 mr-1" /> New Task
            </Button>
          </div>
          {showNewTask && (
            <Card>
              <CardContent className="p-4">
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={newTaskTitle}
                    onChange={(e) => setNewTaskTitle(e.target.value)}
                    placeholder="Task title..."
                    className="flex-1 px-3 py-2 border rounded-md text-sm"
                    onKeyDown={(e) => e.key === 'Enter' && handleAddTask()}
                  />
                  <Button onClick={handleAddTask} disabled={!newTaskTitle.trim()}>
                    Create
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}
          {taskRows.length > 0 ? (
            <DataTable data={taskRows} columns={taskColumns} />
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <Users className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No tasks yet. Create one above.</p>
              </CardContent>
            </Card>
          )}
        </div>
      )}

      {activeTab === 'activity' && (
        <div>
          {activityRows.length > 0 ? (
            <DataTable data={activityRows} columns={activityColumns} />
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <Activity className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No activity recorded yet.</p>
              </CardContent>
            </Card>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';

import { Skeleton } from '@/components/ui/Skeleton';
import { ConsolidationEngine, EntityData, OwnershipStructure } from '@/engines/ConsolidationEngine';
import { AllocationRuleEngine } from '@/engines/AllocationRuleEngine';
import { Plus, Trash2, Edit2, LayoutGrid, List } from 'lucide-react';

interface Entity {
  id: string;
  name: string;
  code: string;
  currency: string;
  country: string;
  parentId: string | null;
  ownershipPct: number;
}

const currencies = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD'];

export default function ConsolidationDashboard() {
  const [entities, setEntities] = useState<Entity[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEntity, setEditingEntity] = useState<Entity | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    code: '',
    currency: 'USD',
    country: '',
    parentId: '',
    ownershipPct: 100,
  });

  const handleAdd = () => {
    setEditingEntity(null);
    setFormData({
      name: '',
      code: '',
      currency: 'USD',
      country: '',
      parentId: '',
      ownershipPct: 100,
    });
    setIsModalOpen(true);
  };

  const handleEdit = (entity: Entity) => {
    setEditingEntity(entity);
    setFormData({
      name: entity.name,
      code: entity.code,
      currency: entity.currency,
      country: entity.country,
      parentId: entity.parentId || '',
      ownershipPct: entity.ownershipPct,
    });
    setIsModalOpen(true);
  };

  const handleDelete = (entity: Entity) => {
    const hasChildren = entities.some((e) => e.parentId === entity.id);
    if (hasChildren) {
      alert(`Cannot delete ${entity.name} because it has child entities.`);
      return;
    }
    if (window.confirm(`Delete ${entity.name}?`)) {
      setEntities(entities.filter((e) => e.id !== entity.id));
    }
  };

  const validate = () => {
    if (formData.name.length < 2) return 'Name must be at least 2 characters';
    if (formData.code.length < 3 || formData.code.length > 8) return 'Code must be 3-8 characters';
    if (
      entities.some(
        (e) => e.code === formData.code && (!editingEntity || e.id !== editingEntity.id)
      )
    ) {
      return 'Code must be unique';
    }
    if (formData.parentId) {
      if (editingEntity && formData.parentId === editingEntity.id)
        return 'Entity cannot be its own parent';

      // Circular check
      let curr = formData.parentId;
      while (curr) {
        const parent = entities.find((e) => e.id === curr);
        if (parent && editingEntity && parent.id === editingEntity.id)
          return 'Circular reference detected';
        curr = parent?.parentId || '';
      }
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const err = validate();
    if (err) {
      alert(err);
      return;
    }

    const newEntity: Entity = {
      id: editingEntity?.id || `ent-${Date.now()}`,
      name: formData.name,
      code: formData.code,
      currency: formData.currency,
      country: formData.country,
      parentId: formData.parentId || null,
      ownershipPct: formData.ownershipPct,
    };

    if (editingEntity) {
      setEntities(entities.map((e) => (e.id === editingEntity.id ? newEntity : e)));
    } else {
      setEntities([...entities, newEntity]);
    }
    setIsModalOpen(false);
  };

  const consolidatedData = useMemo(() => {
    if (entities.length === 0) return null;

    // Mock data for consolidation logic verification
    const entityData: EntityData[] = entities.map((e) => ({
      entityId: e.id,
      entityName: e.name,
      currency: e.currency,
      entries: [
        {
          id: `re-${e.id}`,
          entityId: e.id,
          accountCode: '4000',
          accountName: 'Revenue',
          amount: 100000,
          date: '2024-01-01',
          period: '2024-01',
        },
        {
          id: `ex-${e.id}`,
          entityId: e.id,
          accountCode: '5000',
          accountName: 'Operating Expenses',
          amount: -60000,
          date: '2024-01-01',
          period: '2024-01',
        },
      ],
    }));

    const ownerships: OwnershipStructure[] = entities
      .filter((e) => e.parentId)
      .map((e) => ({
        parentId: e.parentId!,
        childId: e.id,
        ownershipPct: e.ownershipPct,
      }));

    return ConsolidationEngine.consolidate(entityData, ownerships);
  }, [entities]);

  if (isLoading)
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  if (error)
    return (
      <div className="p-12 text-center text-red-500">
        {error}{' '}
        <Button onClick={() => setError(null)} className="ml-4">
          Retry
        </Button>
      </div>
    );

  return (
    <div className="p-6 space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">
            Legal Entity Consolidation
          </h1>
          <p className="text-[var(--text-secondary)] mt-1">
            Manage entity structure and view consolidated financial results.
          </p>
        </div>
        <Button onClick={handleAdd}>
          <Plus className="h-4 w-4 mr-2" /> Add Entity
        </Button>
      </div>

      <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
        <CardHeader>
          <CardTitle>Entity Structure</CardTitle>
        </CardHeader>
        <CardContent>
          {entities.length === 0 ? (
            <div className="py-12 text-center text-[var(--text-secondary)]">
              No entities defined yet. Add your first entity to start consolidation.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)] font-medium">
                  <tr>
                    <th className="py-3 px-4">Name</th>
                    <th className="py-3 px-4">Code</th>
                    <th className="py-3 px-4">Currency</th>
                    <th className="py-3 px-4">Country</th>
                    <th className="py-3 px-4">Parent Entity</th>
                    <th className="py-3 px-4">Ownership %</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                  {entities.map((entity) => (
                    <tr key={entity.id} className="hover:bg-[var(--bg-muted)] transition-colors">
                      <td className="py-3 px-4 font-medium">{entity.name}</td>
                      <td className="py-3 px-4 font-mono">{entity.code}</td>
                      <td className="py-3 px-4">{entity.currency}</td>
                      <td className="py-3 px-4">{entity.country}</td>
                      <td className="py-3 px-4">
                        {entities.find((e) => e.id === entity.parentId)?.name || '-'}
                      </td>
                      <td className="py-3 px-4">{entity.ownershipPct}%</td>
                      <td className="py-3 px-4 text-right space-x-2">
                        <Button variant="outline" size="sm" onClick={() => handleEdit(entity)}>
                          <Edit2 className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="text-red-500 border-red-500/20 hover:bg-red-500/10"
                          onClick={() => handleDelete(entity)}
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {entities.length > 0 && (
        <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
          <CardHeader>
            <CardTitle>Consolidated Profit & Loss (Draft)</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-6">
              <div className="flex gap-4 items-center">
                <div className="text-sm text-[var(--text-secondary)]">Period:</div>
                <Select
                  options={Array.from({ length: 12 }, (_, i) => ({
                    value: `2024-${String(i + 1).padStart(2, '0')}`,
                    label: new Date(2024, i).toLocaleString('default', {
                      month: 'long',
                      year: 'numeric',
                    }),
                  }))}
                  value="2024-01"
                  onChange={() => {}}
                />
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm tabular-nums">
                  <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)]">
                    <tr>
                      <th className="py-3 px-4">Account</th>
                      {entities.map((e) => (
                        <th key={e.id} className="py-3 px-4 text-right">
                          {e.name}
                        </th>
                      ))}
                      <th className="py-3 px-4 text-right">Eliminations</th>
                      <th className="py-3 px-4 text-right font-bold text-blue-400">Consolidated</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                    <tr className="hover:bg-[var(--bg-muted)]">
                      <td className="py-3 px-4">Revenue</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right">
                          $100,000
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right text-red-400">-$0</td>
                      <td className="py-3 px-4 text-right font-bold">
                        ${(entities.length * 100000).toLocaleString()}
                      </td>
                    </tr>
                    <tr className="hover:bg-[var(--bg-muted)]">
                      <td className="py-3 px-4">Operating Expenses</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right">
                          ($60,000)
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right">$0</td>
                      <td className="py-3 px-4 text-right font-bold">
                        (${(entities.length * 60000).toLocaleString()})
                      </td>
                    </tr>
                    <tr className="bg-[var(--bg-muted)] font-bold">
                      <td className="py-3 px-4">Net Income</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right text-green-400">
                          $40,000
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right">$0</td>
                      <td className="py-3 px-4 text-right text-blue-400">
                        ${(entities.length * 40000).toLocaleString()}
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <Card className="w-full max-w-lg mx-4">
            <CardHeader>
              <CardTitle>{editingEntity ? 'Edit Entity' : 'Add New Entity'}</CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Name</label>
                    <Input
                      required
                      placeholder="e.g. US Parent"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Code</label>
                    <Input
                      required
                      maxLength={8}
                      placeholder="e.g. US001"
                      value={formData.code}
                      onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Currency
                    </label>
                    <Select
                      options={currencies.map((c) => ({ value: c, label: c }))}
                      value={formData.currency}
                      onChange={(val) => setFormData({ ...formData, currency: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Country
                    </label>
                    <Input
                      placeholder="e.g. United States"
                      value={formData.country}
                      onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Parent Entity
                    </label>
                    <Select
                      options={[
                        { value: '', label: 'No Parent' },
                        ...entities
                          .filter((e) => !editingEntity || e.id !== editingEntity.id)
                          .map((e) => ({ value: e.id, label: e.name })),
                      ]}
                      value={formData.parentId}
                      onChange={(val) => setFormData({ ...formData, parentId: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Ownership %
                    </label>
                    <Input
                      type="number"
                      min={0}
                      max={100}
                      value={formData.ownershipPct}
                      onChange={(e) =>
                        setFormData({ ...formData, ownershipPct: Number(e.target.value) })
                      }
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-4">
                  <Button variant="outline" type="button" onClick={() => setIsModalOpen(false)}>
                    Cancel
                  </Button>
                  <Button type="submit">{editingEntity ? 'Update Entity' : 'Create Entity'}</Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import {useCallback, useState} from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Modal } from '@/components/ui/Modal';
import {Plus, Trash2, AlertCircle} from 'lucide-react';
import type { ExchangeRate } from '@/types';

const INITIAL_RATES: ExchangeRate[] = [
  { id: '1', fromCurrency: 'USD', toCurrency: 'EUR', rate: 0.92, effectiveDate: '2026-01-01' },
  { id: '2', fromCurrency: 'USD', toCurrency: 'GBP', rate: 0.79, effectiveDate: '2026-01-01' },
  { id: '3', fromCurrency: 'USD', toCurrency: 'JPY', rate: 149.5, effectiveDate: '2026-01-01' },
];

const CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'CNY', 'INR', 'BRL'];

interface RateForm {
  fromCurrency: string;
  toCurrency: string;
  rate: string;
  effectiveDate: string;
}

const EMPTY_FORM: RateForm = {
  fromCurrency: 'USD',
  toCurrency: 'EUR',
  rate: '',
  effectiveDate: '',
};

export default function FXRatesPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [rates, setRates] = useState<ExchangeRate[]>(INITIAL_RATES);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<RateForm>(EMPTY_FORM);
  const [errors, setErrors] = useState<Partial<Record<keyof RateForm, string>>>({});
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const validate = useCallback(
    (f: RateForm): Partial<Record<keyof RateForm, string>> => {
      const e: Partial<Record<keyof RateForm, string>> = {};
      if (!f.rate || isNaN(Number(f.rate)) || Number(f.rate) <= 0)
        e.rate = 'Rate must be a positive number';
      if (f.fromCurrency === f.toCurrency) e.toCurrency = 'Currencies must differ';
      if (rates.some((r) => r.fromCurrency === f.fromCurrency && r.toCurrency === f.toCurrency))
        e.toCurrency = 'This currency pair already exists';
      if (!f.effectiveDate) e.effectiveDate = 'Date is required';
      return e;
    },
    [rates]
  );

  const handleAdd = useCallback(() => {
    const errs = validate(form);
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;
    const newRate: ExchangeRate = {
      id: Date.now().toString(),
      fromCurrency: form.fromCurrency,
      toCurrency: form.toCurrency,
      rate: Number(form.rate),
      effectiveDate: form.effectiveDate,
    };
    setRates((prev) => [...prev, newRate]);
    setForm(EMPTY_FORM);
    setShowForm(false);
  }, [form, validate]);

  const handleDelete = useCallback((id: string) => {
    setRates((prev) => prev.filter((r) => r.id !== id));
    setDeleteId(null);
  }, []);

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-4">Import data to enable FX translation.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">FX Rates</h1>
          <p className="text-sm text-slate-400 mt-1">
            {rates.length} rate{rates.length !== 1 ? 's' : ''} configured
          </p>
        </div>
        <Button
          size="sm"
          onClick={() => {
            setForm(EMPTY_FORM);
            setErrors({});
            setShowForm(true);
          }}
        >
          <Plus className="h-3.5 w-3.5 mr-1.5" />
          Add Rate
        </Button>
      </div>

      <Card>
        <CardContent className="p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                <th className="px-4 py-3">From</th>
                <th className="px-4 py-3">To</th>
                <th className="px-4 py-3 text-right">Rate</th>
                <th className="px-4 py-3">Effective Date</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {rates.length === 0 ? (
                <tr>
                  <td colSpan={5} className="text-center py-12 text-slate-500">
                    <AlertCircle className="h-8 w-8 mx-auto mb-2 text-slate-600" />
                    No exchange rates configured. Add rates to enable multi-currency translation.
                  </td>
                </tr>
              ) : (
                rates.map((r) => (
                  <tr key={r.id} className="hover:bg-slate-900/50">
                    <td className="px-4 py-3 font-mono">{r.fromCurrency}</td>
                    <td className="px-4 py-3 font-mono">{r.toCurrency}</td>
                    <td className="px-4 py-3 text-right tabular-nums font-medium">
                      {r.rate.toFixed(4)}
                    </td>
                    <td className="px-4 py-3 text-slate-400">{r.effectiveDate}</td>
                    <td className="px-4 py-3 text-right">
                      <Button variant="ghost" size="sm" onClick={() => setDeleteId(r.id)}>
                        <Trash2 className="h-3.5 w-3.5 text-red-400" />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Add Rate Modal */}
      <Modal isOpen={showForm} onClose={() => setShowForm(false)}>
        <div className="p-6 space-y-4">
          <h2 className="text-lg font-bold text-white">Add Exchange Rate</h2>
