                    </div>
                  </div>
                );
              })}
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Lease Portfolio</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {mockLeases.map((lease) => (
              <div
