                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      ))}

      {filtered.length === 0 && (
        <div className="text-center py-12 text-slate-400">
          <Search className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>No reports match "{search}"</p>
        </div>
      )}
    </div>
  );
}

