        total: 120000,
        recognized: 90000,
        remaining: 30000,
        nextRecognition: '2026-07-01',
        method: 'Ratable',
      },
      {
        contract: 'Gamma Ltd — Implementation',
        total: 250000,
        recognized: 250000,
        remaining: 0,
