      {
        headers: ['Contract', 'Total', 'Recognized', 'Remaining', 'Next Recognition', 'Method'],
        rows: data.contracts.map((c) => [
          c.contract,
          formatCurrency(c.total),
          formatCurrency(c.recognized),
          formatCurrency(c.remaining),
          c.nextRecognition,
          c.method,
        ]),
      },
      { title: 'Revenue_Recognition_Report' }
