  const columns: Column<ContractRow>[] = [
    { key: 'contract', header: 'Contract', sortable: true },
    {
      key: 'total',
      header: 'Total',
      align: 'right',
      render: (r) => formatCurrency(r.total),
      sortable: true,
    },
    {
      key: 'recognized',
