          <CardTitle>Revenue Target Progress</CardTitle>
        </CardHeader>
        <CardContent className="flex justify-center">
          <GaugeChart
            value={data.recognized}
            max={data.revenue}
            target={data.revenue * 0.9}
            label="Recognized"
            formatValue={(v) => `$${(v / 1000).toFixed(0)}K`}
            ariaLabel="Revenue recognition gauge"
