function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

interface VarianceRow {
  account: string;
  budget: number;
  actual: number;
  variance: number;
  variancePct: number;
  driver: string;
}

export default function VarianceDashboardPage() {
  const { entries } = useGLStore();
  const { budgets } = useBudgetStore();
  const navigate = useNavigate();

  useEffect(() => {
    document.title = 'FinPlan Pro — Variance Dashboard';
  }, []);

  const data = useMemo(() => {
    if (entries.length === 0) return null;
    const actualRevenue = entries
      .filter((e) => (e.accountCode || '').startsWith('4'))
      .reduce((s, e) => s + (e.debit - e.credit), 0);
    const actualCOGS = entries
      .filter((e) => (e.accountCode || '').startsWith('5'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    const actualOpEx = entries
      .filter((e) => (e.accountCode || '').startsWith('6'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    const budgetRevenue =
      budgets
        .filter((b) => b.status === 'Approved')
        .reduce((s, b) => s + (b.totalAmount || 0), 0) || actualRevenue * 1.05;
    const budgetCOGS = actualCOGS * 0.95;
    const budgetOpEx = actualOpEx * 0.93;
    const revenueVar = actualRevenue - budgetRevenue;
    const cogsVar = budgetCOGS - actualCOGS;
    const opexVar = budgetOpEx - actualOpEx;
    const revenueVarPct = budgetRevenue > 0 ? (revenueVar / budgetRevenue) * 100 : 0;
    const rows: VarianceRow[] = [
      {
        account: 'Revenue',
        budget: budgetRevenue,
        actual: actualRevenue,
        variance: revenueVar,
        variancePct: revenueVarPct,
        driver: revenueVar >= 0 ? 'Volume/Mix' : 'Pricing pressure',
      },
      {
        account: 'COGS',
        budget: budgetCOGS,
        actual: actualCOGS,
        variance: cogsVar,
        variancePct: budgetCOGS > 0 ? (cogsVar / budgetCOGS) * 100 : 0,
        driver: cogsVar >= 0 ? 'Cost efficiency' : 'Input cost increase',
      },
      {
        account: 'Operating Expenses',
        budget: budgetOpEx,
        actual: actualOpEx,
        variance: opexVar,
        variancePct: budgetOpEx > 0 ? (opexVar / budgetOpEx) * 100 : 0,
        driver: opexVar >= 0 ? 'Spending control' : 'Hiring ahead of plan',
      },
    ];
    const totalBudget = budgetRevenue + budgetCOGS + budgetOpEx;
    const totalActual = actualRevenue + actualCOGS + actualOpEx;
    const totalVar = totalBudget - totalActual;
    const favorable = rows.filter((r) => r.variance >= 0).reduce((s, r) => s + r.variance, 0);
    const unfavorable = rows
      .filter((r) => r.variance < 0)
      .reduce((s, r) => s + Math.abs(r.variance), 0);
    const chartData = rows.map((r) => ({
      name: r.account,
      favorable: r.variance >= 0 ? r.variance : 0,
      unfavorable: r.variance < 0 ? Math.abs(r.variance) : 0,
    }));
    return {
      actualRevenue,
      budgetRevenue,
      revenueVar,
      revenueVarPct,
      rows,
      totalVar,
      favorable,
      unfavorable,
      chartData,
    };
  }, [entries, budgets]);

  const handleExportPDF = () => {
    if (!data) return;
    ExportEngine.exportToPDF(
      {
        headers: ['Account', 'Budget', 'Actual', 'Variance', 'Variance %', 'Driver'],
        rows: data.rows.map((r) => [
          r.account,
          formatCurrency(r.budget),
          formatCurrency(r.actual),
          formatCurrency(r.variance),
          r.variancePct.toFixed(1) + '%',
          r.driver,
        ]),
      },
      { title: 'Variance Dashboard Report', companyName: 'FinPlan Pro' }
    );
  };

  const handleExportExcel = () => {
    if (!data) return;
    ExportEngine.exportToExcel(
      {
        headers: ['Account', 'Budget', 'Actual', 'Variance', 'Variance %', 'Driver'],
        rows: data.rows.map((r) => [
          r.account,
          formatCurrency(r.budget),
          formatCurrency(r.actual),
          formatCurrency(r.variance),
          r.variancePct.toFixed(1) + '%',
          r.driver,
        ]),
      },
      { title: 'Variance_Dashboard_Report' }
    );
  };

  const columns: Column<VarianceRow>[] = [
    { key: 'account', header: 'Account', sortable: true },
    {
      key: 'budget',
      header: 'Budget',
      align: 'right',
      render: (r) => formatCurrency(r.budget),
      sortable: true,
    },
    {
      key: 'actual',
      header: 'Actual',
      align: 'right',
      render: (r) => formatCurrency(r.actual),
      sortable: true,
    },
    {
      key: 'variance',
      header: 'Variance',
      align: 'right',
      render: (r) => (
        <span className={r.variance >= 0 ? 'text-green-400' : 'text-red-400'}>
          {formatCurrency(r.variance)}
        </span>
      ),
      sortable: true,
    },
    {
      key: 'variancePct',
      header: 'Variance %',
      align: 'right',
      render: (r) => (
        <span className={r.variancePct >= 0 ? 'text-green-400' : 'text-red-400'}>
          {r.variancePct.toFixed(1)}%
        </span>
      ),
      sortable: true,
    },
    { key: 'driver', header: 'Key Driver', sortable: true },
  ];

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <BarChart3 className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-6">Import data and create budgets to see variances.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  if (!data)
    return (
      <div className="p-12 text-center">
        <h2 className="text-lg font-semibold mb-2">No Budget Data</h2>
        <p className="text-slate-400 mb-4">Create approved budgets to compare against actuals.</p>
        <Button onClick={() => navigate('/budgets/create')}>Create Budget</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6 animate-fade-in">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Variance Dashboard</h1>
        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={handleExportPDF} aria-label="Export PDF">
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportExcel} aria-label="Export Excel">
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        </div>
      </div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <KPIValue
          label="Actual Revenue"
          value={formatCurrency(data.actualRevenue)}
          icon={<DollarSign className="h-4 w-4" />}
        />
        <KPIValue
          label="Budget Revenue"
          value={formatCurrency(data.budgetRevenue)}
          icon={<DollarSign className="h-4 w-4" />}
        />
        <KPIValue
          label="Revenue Variance"
          value={formatCurrency(data.revenueVar)}
          icon={
            data.revenueVar >= 0 ? (
              <TrendingUp className="h-4 w-4" />
            ) : (
              <TrendingDown className="h-4 w-4" />
            )
          }
        />
        <KPIValue
          label="Variance %"
          value={`${data.revenueVarPct.toFixed(1)}%`}
          icon={
            data.revenueVarPct >= 0 ? (
              <TrendingUp className="h-4 w-4" />
            ) : (
              <TrendingDown className="h-4 w-4" />
            )
          }
        />
      </div>
      <Card>
        <CardHeader>
          <CardTitle>Variance by Category</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={data.chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={11} />
              <YAxis
                stroke="#94a3b8"
                fontSize={12}
                tickFormatter={(v) => `$${(v / 1000).toFixed(0)}k`}
              />
              <Tooltip
                formatter={(v: any) => formatCurrency(v)}
                contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155' }}
              />
              <Legend />
              <Bar dataKey="favorable" fill="#10b981" name="Favorable" radius={[4, 4, 0, 0]} />
              <Bar dataKey="unfavorable" fill="#ef4444" name="Unfavorable" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Budget vs Actual Variance</CardTitle>
        </CardHeader>
        <CardContent>
          <VarianceChart
            data={data.rows
              .slice(0, 8)
              .map((r) => ({ name: r.account, budget: r.budget, actual: r.actual }))}
            height={200}
            ariaLabel="Budget vs actual variance chart"
          />
        </CardContent>
      </Card>
      <DataTable columns={columns} data={data.rows} />
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { KPIValue } from '@/components/ui/KPIValue';
import { Download, BarChart3, DollarSign, Users, TrendingUp } from 'lucide-react';
import { ExportEngine } from '@/engines/ExportEngine';
import {
  ResponsiveContainer,
  _BarChart,
  _Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  LineChart,
  Line,
} from 'recharts';

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

const LEVELS = [
  { level: 'Junior', min: 50000, max: 75000, headcount: 45, avgPerf: 3.2 },
  { level: 'Mid', min: 75000, max: 110000, headcount: 80, avgPerf: 3.5 },
  { level: 'Senior', min: 110000, max: 160000, headcount: 55, avgPerf: 3.8 },
  { level: 'Staff', min: 160000, max: 220000, headcount: 25, avgPerf: 4.0 },
  { level: 'Principal', min: 220000, max: 300000, headcount: 10, avgPerf: 4.2 },
  { level: 'Director', min: 280000, max: 400000, headcount: 8, avgPerf: 4.1 },
];

export default function CompModelingPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [meritPct, setMeritPct] = useState(3.5);
  useEffect(() => {
    document.title = 'FinPlan Pro — Compensation Modeling';
  }, []);

  const compData = useMemo(
    () =>
      LEVELS.map((l) => {
        const midpoint = (l.min + l.max) / 2;
        const totalCost = midpoint * l.headcount;
        const newCost = totalCost * (1 + meritPct / 100);
        return { ...l, midpoint, totalCost, newCost, increase: newCost - totalCost };
      }),
    [meritPct]
  );

  const projections = useMemo(() => {
    const years = [2026, 2027, 2028, 2029, 2030];
    return years.map((year, i) => ({
      year: String(year),
      current: compData.reduce((s, l) => s + l.totalCost, 0) * Math.pow(1 + meritPct / 100, i),
      projected: compData.reduce((s, l) => s + l.newCost, 0) * Math.pow(1 + meritPct / 100, i),
    }));
  }, [compData, meritPct]);

  const totals = useMemo(() => {
    const currentTotal = compData.reduce((s, l) => s + l.totalCost, 0);
    const newTotal = compData.reduce((s, l) => s + l.newCost, 0);
    return {
      currentTotal,
      newTotal,
      budgetImpact: newTotal - currentTotal,
      totalHeadcount: compData.reduce((s, l) => s + l.headcount, 0),
    };
  }, [compData]);

  const handleExport = () => {
    ExportEngine.exportToExcel(
      {
        headers: [
          'Level',
          'Headcount',
          'Min',
          'Max',
          'Midpoint',
          'Current Cost',
          'New Cost',
          'Increase',
        ],
        rows: compData.map((l) => [
          l.level,
          l.headcount,
          l.min,
          l.max,
          l.midpoint,
          l.totalCost,
          l.newCost,
          l.increase,
        ]),
      },
      { title: 'Compensation_Model' }
    );
  };

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <BarChart3 className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Compensation Data</h2>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Compensation Modeling</h1>
          <p className="text-sm text-slate-400">Model merit increases and budget impact</p>
        </div>
        <Button variant="outline" onClick={handleExport}>
          <Download className="h-4 w-4 mr-2" />
          Export
        </Button>
      </div>

      <div className="grid gap-4 md:grid-cols-4">
        <KPIValue
          label="Total Headcount"
          value={totals.totalHeadcount.toString()}
          icon={<Users className="h-4 w-4" />}
        />
        <KPIValue
          label="Current Total Comp"
          value={formatCurrency(totals.currentTotal)}
          icon={<DollarSign className="h-4 w-4" />}
        />
        <KPIValue
          label="Budget Impact"
          value={formatCurrency(totals.budgetImpact)}
          icon={<TrendingUp className="h-4 w-4" />}
          trend="down"
        />
        <KPIValue
          label="Merit Increase"
          value={`${meritPct}%`}
          icon={<TrendingUp className="h-4 w-4" />}
        />
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Merit Increase: {meritPct}%</CardTitle>
        </CardHeader>
        <CardContent>
          <input
            type="range"
            min={0}
            max={10}
            step={0.5}
            value={meritPct}
            onChange={(e) => setMeritPct(parseFloat(e.target.value))}
            className="w-full accent-blue-500"
          />
          <div className="flex justify-between text-xs text-slate-400 mt-1">
            <span>0%</span>
            <span>5%</span>
            <span>10%</span>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Compensation Bands</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-slate-700">
                  <th className="text-left py-2 px-3 text-slate-400 font-medium">Level</th>
                  <th className="text-right py-2 px-3 text-slate-400 font-medium">HC</th>
                  <th className="text-right py-2 px-3 text-slate-400 font-medium">Band</th>
                  <th className="text-right py-2 px-3 text-slate-400 font-medium">Current Cost</th>
                  <th className="text-right py-2 px-3 text-slate-400 font-medium">New Cost</th>
                  <th className="text-right py-2 px-3 text-slate-400 font-medium">Increase</th>
                </tr>
              </thead>
              <tbody>
                {compData.map((l) => (
                  <tr key={l.level} className="border-b border-slate-800">
                    <td className="py-2 px-3 font-medium">{l.level}</td>
                    <td className="text-right py-2 px-3">{l.headcount}</td>
                    <td className="text-right py-2 px-3">
                      {formatCurrency(l.min)} – {formatCurrency(l.max)}
                    </td>
                    <td className="text-right py-2 px-3">{formatCurrency(l.totalCost)}</td>
                    <td className="text-right py-2 px-3 text-blue-400">
                      {formatCurrency(l.newCost)}
                    </td>
                    <td className="text-right py-2 px-3 text-green-400">
                      +{formatCurrency(l.increase)}
                    </td>
                  </tr>
                ))}
                <tr className="font-bold border-t border-slate-600">
                  <td className="py-2 px-3">Total</td>
                  <td className="text-right py-2 px-3">{totals.totalHeadcount}</td>
                  <td className="text-right py-2 px-3">—</td>
                  <td className="text-right py-2 px-3">{formatCurrency(totals.currentTotal)}</td>
                  <td className="text-right py-2 px-3 text-blue-400">
                    {formatCurrency(totals.newTotal)}
                  </td>
                  <td className="text-right py-2 px-3 text-green-400">
                    +{formatCurrency(totals.budgetImpact)}
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>5-Year Cost Projection</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={projections}>
              <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
              <XAxis dataKey="year" stroke="#94a3b8" />
              <YAxis stroke="#94a3b8" tickFormatter={(v) => `$${(v / 1000000).toFixed(0)}M`} />
              <Tooltip
                contentStyle={{
                  background: '#1e293b',
                  border: '1px solid #334155',
                  borderRadius: 8,
                }}
                formatter={(v: any) => formatCurrency(v)}
              />
              <Legend />
              <Line dataKey="current" name="Current Path" stroke="#64748b" strokeDasharray="5 5" />
              <Line dataKey="projected" name="With Merit" stroke="#3b82f6" strokeWidth={2} />
            </LineChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>
    </div>
  );
}

